<?phpif (!defined('BASEPATH')) {	exit('No direct script access allowed');}include_once APPPATH . '/modules/layout/controllers/Layout.php';class Warehouse extends Layout {	private $_module_slug = 'phieu-nhap/loai-kho-hang';	private $_module_name = 'kho hàng';	function __construct() {		parent::__construct();		$this->load->model('purchase_voucher/m_warehouse', 'M_warehouse');		$this->_data['breadcrumbs_module_name'] = ucfirst($this->_module_name);		$this->_data['breadcrumbs_module_func'] = 'Danh sách';		$this->_data['module_slug'] = $this->_module_slug;		$this->_data['module_name'] = $this->_module_name;		$_breadcrumbs_admin[] = array(			'url' => '',			'name' => ucfirst($this->_module_name),			'image' => base_url('assets/Frest/app-assets/images/svg/ico/ico-shop.svg'),		);		$this->_data['breadcrumbs_admin'] = $_breadcrumbs_admin;	}	private function _validate_access_role(){		$this->validate_access_role('ROLE_GROUP_PURCHASE_VOUCHER');	}	function default_args() {		$order_by = array(			'order' => 'ASC',			'modified' => 'DESC',			'name' => 'ASC',		);		$args = array();		$args['order_by'] = $order_by;		return $args;	}	function counts($options = array()) {		$default_args = $this->default_args();		if (is_array($options) && !empty($options)) {			$args = array_merge($default_args, $options);		} else {			$args = $default_args;		}		return $this->M_warehouse->counts($args);	}	function get($id) {		return $this->M_warehouse->get($id);	}	function get_max_order() {		$args = $this->default_args();		$order_by = array(			'order' => 'DESC',		);		$args['order_by'] = $order_by;		$perpage = 1;		$offset = 0;		$rows = $this->M_warehouse->gets($args, $perpage, $offset);		$max_order = isset($rows[0]['order']) ? $rows[0]['order'] : 0;		return (int) $max_order;	}	function gets($options = array()) {		$default_args = $this->default_args();		if (is_array($options) && !empty($options)) {			$args = array_merge($default_args, $options);		} else {			$args = $default_args;		}		return $this->M_warehouse->gets($args);	}	function gets_in_id() {		$this->load->model('m_warehouse', 'M_warehouse');		$args = $this->default_args();		return $this->M_warehouse->gets($args);	}	function admin_view() {		$this->_initialize_admin();		$this->_validate_access_role();		$id = (int) (($this->uri->segment(3) == '') ? 0 : $this->uri->segment(3));		if ($id == 0) {			show_404();		}		$this->_data['current_page'] = (int) $this->input->get('current_page');		$row = $this->get($id);		$this->_data['row'] = $row;		$this->_data['breadcrumbs_module_func'] = 'Xem thông tin ' . $this->_module_name;		$this->_data['title'] = 'Xem thông tin ' . $this->_module_name . ' - ' . $this->_data['breadcrumbs_module_name'];		$this->_data['main_content'] = 'admin/view_page_view';		$this->load->view('layout/admin/view_layout', $this->_data);	}	function admin_index() {		$this->_initialize_admin();		$this->_validate_access_role();		$this->_plugins_css_admin[] = array(			'folder' => 'bootstrap3-dialog/css',			'name' => 'bootstrap-dialog',		);		$this->_plugins_script_admin[] = array(			'folder' => 'bootstrap3-dialog/js',			'name' => 'bootstrap-dialog',		);		$this->set_plugins_admin();		$this->_modules_script[] = array(			'folder' => 'warehouse',			'name' => 'admin-items',		);		$this->set_modules();		$get = $this->input->get();		$this->_data['get'] = $get;		$args = $this->default_args();		if (isset($get['q']) && trim($get['q']) != '') {			$args['name'] = $get['q'];		}		$total = $this->counts($args);		$perpage = isset($get['per_page']) ? $get['per_page'] : $this->config->item('per_page');		$segment = 3;		$this->load->library('pagination');		$config['total_rows'] = $total;		$config['per_page'] = $perpage;		$config['full_tag_open'] = '<ul class="pagination no-margin pull-right">';		$config['full_tag_close'] = '</ul><!--pagination-->';		$config['first_link'] = '&laquo;';		$config['first_tag_open'] = '<li class="prev page">';		$config['first_tag_close'] = '</li>';		$config['last_link'] = '&raquo;';		$config['last_tag_open'] = '<li class="next page">';		$config['last_tag_close'] = '</li>';		$config['next_link'] = 'Trang trước &rarr;';		$config['next_tag_open'] = '<li class="next page">';		$config['next_tag_close'] = '</li>';		$config['prev_link'] = '&larr; Trang sau';		$config['prev_tag_open'] = '<li class="prev page">';		$config['prev_tag_close'] = '</li>';		$config['cur_tag_open'] = '<li class="active"><a href="">';		$config['cur_tag_close'] = '</a></li>';		$config['num_tag_open'] = '<li class="page">';		$config['num_tag_close'] = '</li>';		if (!empty($get)) {			$config['base_url'] = base_url($this->_module_slug);			$config['suffix'] = '?' . http_build_query($get, '', "&");			$config['first_url'] = base_url($this->_module_slug . '?' . http_build_query($get, '', "&"));			$config['uri_segment'] = $segment;		} else {			$config['base_url'] = base_url($this->_module_slug);			$config['uri_segment'] = $segment;		}		$this->pagination->initialize($config);		$pagination = $this->pagination->create_links();		$this->_data['pagination'] = $pagination;		$offset = ($this->uri->segment($segment) == '') ? 0 : $this->uri->segment($segment);		$rows = $this->M_warehouse->gets($args, $perpage, $offset);        if(is_array($rows) && !empty($rows)){            foreach ($rows as $key => $value) {            	$data = $this->get_inventory_by_warehouse($value['id']);            	$rows[$key]['quantity_purchase_voucher_import_warehouse'] = $data['quantity_purchase_voucher_import_warehouse'];            	$rows[$key]['quantity_purchase_voucher_transaction_warehouse_addition'] = $data['quantity_purchase_voucher_transaction_warehouse_addition'];            	$rows[$key]['quantity_purchase_voucher_transaction_warehouse_subtraction'] = $data['quantity_purchase_voucher_transaction_warehouse_subtraction'];            	$rows[$key]['quantity_purchase_voucher'] = $data['quantity_purchase_voucher'];                $rows[$key]['quantity_output_voucher'] = $data['quantity_output_voucher'];                $rows[$key]['quantity'] = $data['quantity'];            }        }		$this->_data['rows'] = $rows;		$this->_data['title'] = 'Danh sách ' . $this->_module_name . ' - ' . $this->_data['title'];		$this->_data['main_content'] = 'admin/view_page_warehouse_index';		$this->load->view('layout/admin/view_layout', $this->_data);	}	public function get_inventory_by_warehouse($warehouse_id = 0){		$data = array();		$total_quantity_purchase_voucher_import_warehouse = $total_quantity_purchase_voucher_transaction_warehouse_subtraction = $total_quantity_purchase_voucher_transaction_warehouse_addition = 0;    	$products_purchase_voucher_import_details = $this->M_purchase_voucher_details->gets(array(    		'warehouse_id' => $warehouse_id,    		'type' => 'import',    	));    	if(is_array($products_purchase_voucher_import_details) && !empty($products_purchase_voucher_import_details)){    		$total_quantity_purchase_voucher_import_warehouse = array_sum(array_column($products_purchase_voucher_import_details, 'quantity'));    	}    	$products_purchase_voucher_transaction_subtraction_details = $this->M_purchase_voucher_details->gets(array(    		'warehouse_id' => $warehouse_id,    		'type' => 'transaction',    	));    	if(is_array($products_purchase_voucher_transaction_subtraction_details) && !empty($products_purchase_voucher_transaction_subtraction_details)){    		$total_quantity_purchase_voucher_transaction_warehouse_subtraction = array_sum(array_column($products_purchase_voucher_transaction_subtraction_details, 'quantity'));    	}    	$products_purchase_voucher_transaction_addition_details = $this->M_purchase_voucher_details->gets(array(    		'transaction_warehouse_id' => $warehouse_id,    		'type' => 'transaction',    	));    	if(is_array($products_purchase_voucher_transaction_addition_details) && !empty($products_purchase_voucher_transaction_addition_details)){    		$total_quantity_purchase_voucher_transaction_warehouse_addition = array_sum(array_column($products_purchase_voucher_transaction_addition_details, 'quantity'));    	}    	$total_quantity_purchase_voucher = $total_quantity_purchase_voucher_import_warehouse - $total_quantity_purchase_voucher_transaction_warehouse_subtraction + $total_quantity_purchase_voucher_transaction_warehouse_addition;    	$products_output_voucher_details = $this->M_output_voucher_details->gets(array(    		'warehouse_id' => $warehouse_id    	));    	$total_quantity_output_voucher = 0;    	if(is_array($products_output_voucher_details) && !empty($products_output_voucher_details)){    		$total_quantity_output_voucher = array_sum(array_column($products_output_voucher_details, 'quantity'));    	}        $data['quantity_purchase_voucher_import_warehouse'] = $total_quantity_purchase_voucher_import_warehouse;        $data['quantity_purchase_voucher_transaction_warehouse_addition'] = $total_quantity_purchase_voucher_transaction_warehouse_addition;        $data['quantity_purchase_voucher_transaction_warehouse_subtraction'] = $total_quantity_purchase_voucher_transaction_warehouse_subtraction;        $data['quantity_purchase_voucher'] = $total_quantity_purchase_voucher;        $data['quantity_output_voucher'] = $total_quantity_output_voucher;        $data['quantity'] = $total_quantity_purchase_voucher - $total_quantity_output_voucher;        return $data;	}	function add($data) {		if (!is_array($data) || empty($data)) {			return 0;		}		return $this->M_warehouse->add($data);	}	function admin_add() {		$data = array(			'name' => $this->input->post('name'),			'store' => $this->input->post('store'),			'address' => $this->input->post('address'),			'phone' => $this->input->post('phone'),			'created' => time(),			'modified' => 0,			'order' => $this->get_max_order() + 1,			'status' => 1,		);		return $this->add($data);	}	function update($id, $data) {		if (!is_array($data) || empty($data)) {			return 0;		}		return $this->M_warehouse->update($id, $data);	}	function admin_update($id) {		$data = array(			'name' => $this->input->post('name'),			'store' => $this->input->post('store'),			'address' => $this->input->post('address'),			'phone' => $this->input->post('phone'),			'modified' => time(),		);		return $this->update($id, $data);	}	function re_order() {		$args = $this->default_args();		$order_by = array(			'order' => 'ASC',		);		$args['order_by'] = $order_by;		$rows = $this->M_warehouse->gets($args);		if (is_array($rows) && !empty($rows)) {			$i = 0;			foreach ($rows as $value) {				$i++;				$data = array(					'order' => $i,				);				$this->M_warehouse->update($value['id'], $data);			}		}	}	function admin_delete() {		$this->_initialize_admin();		$this->_validate_access_role();		$this->_message_success = 'Đã xóa ' . $this->_module_name . '!';		$this->_message_warning = ucfirst($this->_module_name) . ' này không tồn tại!';		$id = $this->input->get('id');		$row = $this->get($id);		if ($id != 0 && !empty($row)) {			$is_used = false;			$products_purchase_voucher_details = $this->M_purchase_voucher_details->gets(array(				'warehouse_id' => $id			));			if(is_array($products_purchase_voucher_details) && !empty($products_purchase_voucher_details)){				$is_used = true;			}			$products_purchase_voucher_transaction_details = $this->M_purchase_voucher_details->gets(array(				'transaction_warehouse_id' => $id			));			if(is_array($products_purchase_voucher_transaction_details) && !empty($products_purchase_voucher_transaction_details)){				$is_used = true;			}			$products_output_voucher_details = $this->M_output_voucher_details->gets(array(				'warehouse_id' => $id			));			if(is_array($products_output_voucher_details) && !empty($products_output_voucher_details)){				$is_used = true;			}			if($is_used){				$notify_type = 'danger';				$notify_content = ucfirst($this->_module_name) . ' này đang sử dụng nên không xóa được!';			} elseif ($this->M_warehouse->delete($id)) {				add_activities(array(					'action' => NULL,					'activity' => "Người dùng xóa " . $this->_module_name . " #ID: $id",					'data' => serialize(array('old' => $row, 'new' => NULL)),				));				$this->re_order();				$notify_type = 'success';				$notify_content = $this->_message_success;			} else {				$notify_type = 'danger';				$notify_content = $this->_message_danger;			}		} else {			$notify_type = 'warning';			$notify_content = $this->_message_warning;		}		$this->set_notify_admin($notify_type, $notify_content);		redirect(base_url($this->_module_slug));	}	function admin_main() {		$this->_initialize_admin();		$this->_validate_access_role();		$post = $this->input->post();		if (!empty($post)) {			$action = $this->input->post('action');			if ($action == 'update') {				$this->_message_success = 'Đã cập nhật ' . $this->_module_name . '!';				$this->_message_warning = 'Không có ' . $this->_module_name . ' nào để cập nhật!';				$ids = $this->input->post('ids');				$orders = $this->input->post('order');				$count = count($orders);				if (!empty($ids) && !empty($orders)) {					for ($i = 0; $i < $count; $i++) {						$data = array(							'order' => $orders[$i],						);						$id = $ids[$i];						if ($this->M_warehouse->update($id, $data)) {							$notify_type = 'success';							$notify_content = $this->_message_success;						} else {							$notify_type = 'danger';							$notify_content = $this->_message_danger;						}					}				} else {					$notify_type = 'warning';					$notify_content = $this->_message_warning;				}				$this->set_notify_admin($notify_type, $notify_content);				redirect(base_url($this->_module_slug));			} elseif ($action == 'delete') {				$this->_message_success = 'Đã xóa các ' . $this->_module_name . ' được chọn!';				$this->_message_warning = 'Bạn chưa chọn ' . $this->_module_name . ' nào!';				$ids = $this->input->post('idcheck');				if (is_array($ids) && !empty($ids)) {					foreach ($ids as $id) {						if ($this->M_warehouse->delete($id)) {							$notify_type = 'success';							$notify_content = $this->_message_success;						} else {							$notify_type = 'danger';							$notify_content = $this->_message_danger;						}					}					add_activity("Người dùng xóa các " . $this->_module_name . " #ID: " . implode(', ', $ids));					$this->re_order();				} else {					$notify_type = 'warning';					$notify_content = $this->_message_warning;				}				$this->set_notify_admin($notify_type, $notify_content);				redirect(base_url($this->_module_slug));			} elseif ($action == 'content') {				redirect(base_url($this->_module_slug . '/them'));			}		} else {			redirect(base_url($this->_module_slug));		}	}	function admin_content() {		$this->_initialize_admin();		$this->_validate_access_role();		$this->_plugins_script_admin[] = array(			'folder' => 'jquery-validation',			'name' => 'jquery.validate',		);		$this->_plugins_script_admin[] = array(			'folder' => 'jquery-validation/localization',			'name' => 'messages_vi',		);		$this->set_plugins_admin();		$this->_modules_script[] = array(			'folder' => 'warehouse',			'name' => 'admin-validate-content',		);		$this->set_modules();		$post = $this->input->post();		if (!empty($post)) {			$this->load->helper('language');			$this->lang->load('form_validation', 'vietnamese');			$this->form_validation->set_error_delimiters('<span class="help-block">', '</span>');			$this->form_validation->set_rules('name', 'Tên ' . $this->_module_name, 'trim|required');			$this->form_validation->set_rules('store', 'Tên cửa hàng', 'trim|required');			$this->form_validation->set_rules('phone', 'Điện thoại', 'trim|required');			$this->form_validation->set_rules('address', 'Địa chỉ', 'trim|required');			if ($this->form_validation->run($this)) {				if ($this->input->post('id')) {					$err = FALSE;					$id = $this->input->post('id');					$row_old = $this->get($id);					if (!$this->admin_update($id)) {						$err = TRUE;					}					if ($err === FALSE) {						$row_new = $this->get($id);						add_activities(array(							'action' => NULL,							'activity' => "Người dùng cập nhật " . $this->_module_name . " #ID: $id",							'data' => serialize(array('old' => $row_old, 'new' => $row_new)),						));						$notify_type = 'success';						$notify_content = 'Cập nhật ' . $this->_module_name . ' thành công!';						$this->set_notify_admin($notify_type, $notify_content);						redirect(base_url($this->_module_slug));					} else {						$notify_type = 'danger';						$notify_content = 'Có lỗi xảy ra!';						$this->set_notify_admin($notify_type, $notify_content);					}				} else {					$err = FALSE;					$insert_id = $this->admin_add();					if ($insert_id == 0) {						$err = TRUE;					}					if ($err === FALSE) {						$row_new = $this->get($insert_id);						add_activities(array(							'action' => NULL,							'activity' => "Người dùng thêm " . $this->_module_name . " #ID: $insert_id",							'data' => serialize(array('old' => NULL, 'new' => $row_new)),						));						$notify_type = 'success';						$notify_content = ucfirst($this->_module_name) . ' đã được thêm!';						$this->set_notify_admin($notify_type, $notify_content);						redirect(base_url($this->_module_slug));					} else {						$notify_type = 'danger';						$notify_content = 'Có lỗi xảy ra!';						$this->set_notify_admin($notify_type, $notify_content);					}				}			}		}		$title = 'Thêm ' . $this->_module_name . ' - ' . $this->_data['breadcrumbs_module_name'] . ' - ' . $this->_data['title'];		$segment = 4;		$id = ($this->uri->segment($segment) == '') ? 0 : $this->uri->segment($segment);		if ($id != 0) {			$row = $this->get($id);			$this->_data['row'] = $row;			$title = 'Cập nhật ' . $this->_module_name . ' - ' . $this->_data['breadcrumbs_module_name'] . ' - ' . $this->_data['title'];		}		$this->_data['title'] = $title;		$this->_data['main_content'] = 'admin/view_page_warehouse_content';		$this->load->view('layout/admin/view_layout', $this->_data);	}}/* End of file warehouses.php *//* Location: ./application/modules/purchase_voucher/controllers/warehouses.php */